INSERT INTO projects (id,slug,title,status,type,location,year,description_en,description_ro,home,home_index,sort_index) VALUES ('project-5','the-line-interior-design','THE LINE','completed','Interior Design / Residential','Sibiu, Romania','2025','The design concept is built around a continuous horizontal band of color that visually anchors and unifies the kitchen, dining and living areas. A folding glass partition separates the kitchen from the dining space, allowing it to open up entirely or close off as needed - offering flexibility without compromising flow. The result is a balanced, functional interior where cohesion and comfort defines the experience.','Conceptul este construit în jurul unei benzi orizontale continue de culoare, care ancorează vizual și unifică bucătăria, zona de dining și livingul. O partiție vitrată pliantă separă bucătăria de zona de dining, permițând deschiderea completă sau închiderea acesteia după nevoie — flexibilitate fără a compromite fluxul spațial. Rezultatul este un interior echilibrat și funcțional, în care coerența și confortul definesc experiența.',0,NULL,4);
