INSERT INTO projects (id,slug,title,status,type,location,year,description_en,description_ro,home,home_index,sort_index) VALUES ('project-10','adr-north-west-interior-design','ADR NORTH-WEST','completed','Interior Design / Offices','Cluj Napoca, Romania','2026','The working areas are organized as open and adaptable layouts, structured to ensure functional efficiency and spatial coherence. A controlled and consistent environment is defined by daylight access, clear circulation, and rationally proportioned workstations. The design supports both individual tasks and team-based activities.','Zonele de lucru sunt organizate ca spații deschise și adaptabile, structurate pentru a asigura eficiență funcțională și coerență spațială. Un mediu controlat și constant este definit prin accesul la lumină naturală, circulații clare și posturi de lucru proporționate rațional. Configurația sprijină deopotrivă activitatea individuală și lucrul în echipă.',0,NULL,9);
